-- title: Shop
-- description: An online shop: customers, products, categories, orders and order items (January 2025 - June 2026). Used for most SQL lessons and projects.
--
-- Tables: customers, categories, products, orders, order_items
-- This file is read-only sample data for the SQL Lab. The app copies it into a
-- practice database, so your experiments never change this file.
-- Generated by tools/generate_datasets.py

PRAGMA foreign_keys = ON;

CREATE TABLE customers (
    id          INTEGER PRIMARY KEY,
    first_name  TEXT NOT NULL,
    last_name   TEXT NOT NULL,
    email       TEXT UNIQUE,              -- NULL when the customer gave no email
    city        TEXT NOT NULL,
    country     TEXT NOT NULL,
    signup_date TEXT NOT NULL,
    segment     TEXT NOT NULL CHECK (segment IN ('Consumer', 'Small Business', 'Corporate'))
);

CREATE TABLE categories (
    id   INTEGER PRIMARY KEY,
    name TEXT NOT NULL UNIQUE
);

CREATE TABLE products (
    id           INTEGER PRIMARY KEY,
    name         TEXT NOT NULL,
    category_id  INTEGER NOT NULL REFERENCES categories (id),
    price        REAL NOT NULL CHECK (price > 0),   -- selling price
    cost         REAL NOT NULL CHECK (cost >= 0),   -- what the shop paid
    stock        INTEGER NOT NULL DEFAULT 0,
    discontinued INTEGER NOT NULL DEFAULT 0          -- 1 = no longer sold, 0 = active
);

CREATE TABLE orders (
    id            INTEGER PRIMARY KEY,
    customer_id   INTEGER NOT NULL REFERENCES customers (id),
    order_date    TEXT NOT NULL,
    status        TEXT NOT NULL CHECK (status IN ('pending', 'shipped', 'delivered', 'cancelled', 'returned')),
    shipping_city TEXT NOT NULL
);

CREATE TABLE order_items (
    id         INTEGER PRIMARY KEY,
    order_id   INTEGER NOT NULL REFERENCES orders (id),
    product_id INTEGER NOT NULL REFERENCES products (id),
    quantity   INTEGER NOT NULL CHECK (quantity > 0),
    unit_price REAL NOT NULL,        -- price at the time of the order
    discount   REAL NOT NULL DEFAULT 0 CHECK (discount BETWEEN 0 AND 1)  -- 0.1 = 10% off
);





